{"query":"
    query DynamicWebContent($pageType: DynamicWebContentPageType!, $isContentPreviewEnabled: Boolean = false) {
  dynamicWebContent(
    filters: {contentId: "organizationLogos", pageType: $pageType, isContentPreviewEnabled: $isContentPreviewEnabled}
  ) {
    heading
    contents {
      image {
        url
        altText
      }
    }
  }
}
    ","variables":{"pageType":"LOGGED_OUT_HOME_PAGE","isContentPreviewEnabled":false}}

{"query":"
    query SubscriptionPlans($filters: SubscriptionPlanFilters, $licenseCount: Int) {
  subscriptionPlans(filters: $filters) {
    id
    productType
    urlLearnMore
    urlExpressCheckout
    urlTermsOfUse
    contentCollections {
      id
    }
    priceOptions(licenseCount: $licenseCount) {
      ... on MonthlySubscriptionPlanPricingOption {
        id
        listPrice {
          amount
          currency
        }
        price {
          list
          discount
          monthly
          annualSavings
          discountMonthly
          discountAnnualSavings
          currency
        }
        discountTrial {
          dateInterval {
            type
            count
          }
        }
        discount {
          appliedDiscounts {
            code
            discountType
            isRemovable
            sourceType
            data {
              ... on SubscriptionPlanTrialDiscountData {
                days
              }
              ... on SubscriptionPlanPriceDiscountData {
                type
                value
                interval {
                  start
                  end
                  type
                  duration
                }
              }
            }
          }
        }
        renewalInterval {
          type
          count
        }
        trial {
          dateInterval {
            type
            count
          }
        }
        licenseContext {
          unitPrice {
            amount
            currency
          }
          licenseCount
          defaultLicenseCount
          minimumLicenseCount
          maximumLicenseCount
        }
      }
      ... on AnnualSubscriptionPlanPricingOption {
        id
        listPrice {
          amount
          currency
        }
        price {
          list
          discount
          monthly
          annualSavings
          discountMonthly
          discountAnnualSavings
          currency
        }
        discountTrial {
          dateInterval {
            type
            count
          }
        }
        discount {
          appliedDiscounts {
            code
            discountType
            isRemovable
            sourceType
            data {
              ... on SubscriptionPlanTrialDiscountData {
                days
              }
              ... on SubscriptionPlanPriceDiscountData {
                type
                value
                interval {
                  start
                  end
                  type
                  duration
                }
              }
            }
          }
        }
        annualSavings {
          amount
          currency
        }
        monthlyPrice {
          amount
          currency
        }
        renewalInterval {
          type
          count
        }
        trial {
          dateInterval {
            type
            count
          }
        }
        licenseContext {
          unitPrice {
            amount
            currency
          }
          licenseCount
          defaultLicenseCount
          minimumLicenseCount
          maximumLicenseCount
        }
      }
      ... on WeeklySubscriptionPlanPricingOption {
        id
        listPrice {
          amount
          currency
        }
        price {
          list
          discount
          monthly
          annualSavings
          discountMonthly
          discountAnnualSavings
          currency
        }
        discountTrial {
          dateInterval {
            type
            count
          }
        }
        discount {
          appliedDiscounts {
            code
            discountType
            isRemovable
            sourceType
            data {
              ... on SubscriptionPlanTrialDiscountData {
                days
              }
              ... on SubscriptionPlanPriceDiscountData {
                type
                value
                interval {
                  start
                  end
                  type
                  duration
                }
              }
            }
          }
        }
        renewalInterval {
          type
          count
        }
        trial {
          dateInterval {
            type
            count
          }
        }
        licenseContext {
          unitPrice {
            amount
            currency
          }
          licenseCount
          defaultLicenseCount
          minimumLicenseCount
          maximumLicenseCount
        }
      }
      ... on DailySubscriptionPlanPricingOption {
        id
        listPrice {
          amount
          currency
        }
        price {
          list
          discount
          monthly
          annualSavings
          discountMonthly
          discountAnnualSavings
          currency
        }
        discountTrial {
          dateInterval {
            type
            count
          }
        }
        discount {
          appliedDiscounts {
